    "C": "anybody là đại từ bất định dùng trong câu phủ định hoặc nghi vấn, không phù hợp với cấu trúc câu khẳng định mang nghĩa đối lập qua 'but'.",
    "D": "whoever tạo thành một mệnh đề danh từ nhưng cấu trúc câu đã thiếu chủ ngữ chính cho động từ 'got', nên không thể dùng đại từ quan hệ/nghi vấn này."
  },
  "difficulty": "medium"
}

